from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const pill=','const notice=','const heading=','const categoryDefs=','function capabilities(')))
script=defs+'''
const cases=[];for(const language of ['ko','en'])for(const width of [478,610,656,858,904,1118]){lang=language;const f=document.createElement('div');f.className='fixture';f.style.width=(width+2)+'px';f.innerHTML=capabilities();f.querySelectorAll('.page-heading,.notice,.section').forEach(x=>x.remove());document.getElementById('fixtures').append(f);[...f.querySelectorAll('tbody tr')].forEach((row,i)=>{const id=language+'-'+width+'-'+i;row.dataset.id=id;cases.push({id,english:language==='en',key:categoryDefs[i].key,last:i===3,columns:[...row.cells].map(c=>c.getBoundingClientRect().width)})})}
function read(){return [...document.querySelectorAll('tbody tr')].map(e=>{const r=e.getBoundingClientRect(),box=x=>{if(!x)return null;const q=x.getBoundingClientRect();return{x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height}},detail=e.querySelector('.capability-details'),b=e.querySelector('button');return{id:e.dataset.id,root:box(e),description:box(e.querySelector('small')),connected:box(e.querySelectorAll('.pill')[0]),capability:box(e.querySelectorAll('.pill')[1]),details:box(detail),detailText:box(detail.querySelector('span')),button:box(b),columns:[...e.cells].map(c=>c.getBoundingClientRect().width),texts:[e.querySelector('strong').textContent,e.querySelector('small').textContent,...[...e.querySelectorAll('.pill')].map(p=>p.textContent),detail.querySelector('span').textContent,b?.textContent??null]}})}
document.getElementById('capabilityrow-record').onclick=async()=>{await document.fonts.ready;const res=await fetch('/evidence/preflight-capabilityrow-'+(new URLSearchParams(location.search).get('os')==='mac'?'mac':'windows')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:read(),cases})});if(!res.ok)throw Error('Record failed');document.getElementById('capabilityrow-record').textContent='Capability rows recorded'};
'''
(o/'capabilityrow-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes());(o/'capabilityrow.html').write_text('<!doctype html><meta charset="utf-8"><title>CapabilityRow · original isolation</title><link rel="stylesheet" href="capabilityrow-original.css"><style>.fixture{position:absolute;left:30px;top:40px}.fixture:not(:first-child){visibility:hidden}.fixture *{animation:none!important;transition:none!important}</style><div id="fixtures"></div><button id="capabilityrow-record" style="position:fixed;right:20px;top:20px">Record CapabilityRow</button><script>'+script+'</script>');print('48 source capability rows prepared')
